import { useState } from "react";
import { Link } from "react-router-dom";

function Profile({ isLoggedIn }) {

  const [profile, setProfile] = useState({
    name: "",
    email: "",
    dob: "",
    username: "",
    password: ""
  });

  const handleChange = (e) => {
    setProfile({
      ...profile,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Profile Updated Successfully ✅");
  };

  // ✅ If NOT logged in
  if (!isLoggedIn) {
    return (
      <div style={outerStyle}>
        <div style={cardStyle}>
          <h2 style={{ textAlign: "center" }}>
            Please Login First
          </h2>

          <div style={{ textAlign: "center", marginTop: "20px" }}>
            <Link to="/login" style={buttonStyle}>
              Go to Login
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // ✅ If logged in
  return (
    <div style={outerStyle}>
      <div style={cardStyle}>

        <h2 style={headingStyle}>My Profile</h2>

        <form onSubmit={handleSubmit}>

          <input
            type="text"
            name="name"
            placeholder="Full Name"
            value={profile.name}
            onChange={handleChange}
            style={inputStyle}
            required
          />

          <input
            type="email"
            name="email"
            placeholder="Email"
            value={profile.email}
            onChange={handleChange}
            style={inputStyle}
            required
          />

          <input
            type="date"
            name="dob"
            value={profile.dob}
            onChange={handleChange}
            style={inputStyle}
            required
          />

          <input
            type="text"
            name="username"
            placeholder="Username"
            value={profile.username}
            onChange={handleChange}
            style={inputStyle}
            required
          />

          <input
            type="password"
            name="password"
            placeholder="Password"
            value={profile.password}
            onChange={handleChange}
            style={inputStyle}
            required
          />

          <button type="submit" style={buttonStyle}>
            Save Changes
          </button>

        </form>

      </div>
    </div>
  );
}

//////////////////////////////////////////////////////////////
// Styles
//////////////////////////////////////////////////////////////

const outerStyle = {
  minHeight: "100vh",
  backgroundColor: "#b7cdd6",
  display: "flex",
  justifyContent: "center",
  alignItems: "center"
};

const cardStyle = {
  backgroundColor: "white",
  width: "400px",
  padding: "40px",
  borderRadius: "15px",
  boxShadow: "0 10px 30px rgba(0,0,0,0.1)"
};

const headingStyle = {
  textAlign: "center",
  marginBottom: "25px",
  color: "#1177aa"
};

const inputStyle = {
  width: "100%",
  padding: "12px",
  marginBottom: "15px",
  borderRadius: "8px",
  border: "1px solid #ccc",
  fontSize: "14px"
};

const buttonStyle = {
  display: "inline-block",
  width: "100%",
  padding: "12px",
  borderRadius: "8px",
  border: "none",
  backgroundColor: "#1177aa",
  color: "white",
  fontSize: "16px",
  cursor: "pointer",
  textDecoration: "none",
  textAlign: "center"
};

export default Profile;
